/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8mb4 */;
CREATE TABLE `camsPunch` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `user_id` varchar(64) NOT NULL,
  `punch_date_str` varchar(10) NOT NULL,
  `punch_time` datetime NOT NULL,
  `actual_punch_type` smallint(6) NOT NULL COMMENT '0-CheckIn, 1-CheckOut, 3-BreakOut, 4-BreakIn, 5-Intermediate',
  `punch_type` smallint(6) NOT NULL DEFAULT 9 COMMENT 'Recalculated punch type',
  `input_type` smallint(6) NOT NULL COMMENT '0-Fingerprint, 1-Face, 3-Card, 4-Password, 5-Others',
  `device_id` bigint(20) NOT NULL,
  `status` varchar(1) NOT NULL DEFAULT 'A',
  `time_updated` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_user_date` (`user_id`,`punch_date_str`),
  KEY `idx_punch_time` (`punch_time`),
  KEY `idx_device` (`device_id`)
) ENGINE=InnoDB AUTO_INCREMENT=1264 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

