--
-- Table structure for table `mx_attendance`
--

DROP TABLE IF EXISTS `mx_attendance`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8mb4 */;
CREATE TABLE `mx_attendance` (
  `attendanceID` int(11) NOT NULL AUTO_INCREMENT,
  `userID` int(11) NOT NULL,
  `attendanceDate` date NOT NULL,
  `scheduledIn` time DEFAULT '09:00:00',
  `scheduledOut` time DEFAULT '18:00:00',
  `checkIn` datetime DEFAULT NULL,
  `checkOut` datetime DEFAULT NULL,
  `workingHours` decimal(5,2) DEFAULT 0.00,
  `isLate` tinyint(4) DEFAULT 0,
  `isEarlyCheckout` tinyint(4) DEFAULT 0,
  `lateMinutes` int(11) DEFAULT 0,
  `earlyMinutes` int(11) DEFAULT 0,
  `attendanceStatus` enum('present','absent','half_day','leave','holiday','weekend') DEFAULT 'present',
  `source` enum('biometric','manual','system','auto') DEFAULT 'biometric',
  `biometricRaw` text DEFAULT NULL,
  `remarks` text DEFAULT NULL,
  `syncedAt` datetime DEFAULT NULL,
  `status` tinyint(4) DEFAULT 1,
  `createdAt` datetime DEFAULT current_timestamp(),
  PRIMARY KEY (`attendanceID`),
  UNIQUE KEY `unique_attendance` (`userID`,`attendanceDate`),
  KEY `idx_date` (`attendanceDate`),
  KEY `idx_user_month` (`userID`,`attendanceDate`),
  KEY `idx_status` (`attendanceStatus`)
) ENGINE=InnoDB AUTO_INCREMENT=2942 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

