  `userID` int(11) NOT NULL,
  `leaveTypeID` int(11) NOT NULL,
  `financialYear` varchar(10) NOT NULL COMMENT 'Format: 2025-26',
  `openingBalance` decimal(5,2) DEFAULT 0.00 COMMENT 'Balance at start of FY (carry forward)',
  `credited` decimal(5,2) DEFAULT 0.00 COMMENT 'Leaves credited during FY',
  `used` decimal(5,2) DEFAULT 0.00 COMMENT 'Leaves taken',
  `lapsed` decimal(5,2) DEFAULT 0.00 COMMENT 'Leaves that lapsed (not carried forward)',
  `encashed` decimal(5,2) DEFAULT 0.00 COMMENT 'Leaves encashed',
  `adjusted` decimal(5,2) DEFAULT 0.00 COMMENT 'Manual adjustments (+/-)',
  `adjustmentRemarks` text DEFAULT NULL,
  `closingBalance` decimal(5,2) DEFAULT 0.00 COMMENT 'Current/closing balance',
  `lastAccrualDate` date DEFAULT NULL COMMENT 'Last date when monthly accrual was done',
  `createdAt` datetime DEFAULT current_timestamp(),
  `updatedAt` datetime DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`balanceID`),
  UNIQUE KEY `user_leave_fy` (`userID`,`leaveTypeID`,`financialYear`),
  KEY `idx_user` (`userID`),
  KEY `idx_fy` (`financialYear`)
) ENGINE=InnoDB AUTO_INCREMENT=113 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
