CREATE TABLE `mx_leave_encashment` (
  `encashmentID` int(11) NOT NULL AUTO_INCREMENT,
  `userID` int(11) NOT NULL,
  `leaveTypeID` int(11) NOT NULL,
  `financialYear` varchar(10) NOT NULL,
  `encashmentDate` date NOT NULL,
  `daysEncashed` decimal(5,2) NOT NULL,
  `basicSalaryPerDay` decimal(12,2) NOT NULL,
  `encashmentRate` decimal(5,2) DEFAULT 100.00 COMMENT 'Percentage of basic',
  `grossAmount` decimal(12,2) NOT NULL,
  `taxDeducted` decimal(12,2) DEFAULT 0.00,
  `netAmount` decimal(12,2) NOT NULL,
  `encashmentStatus` enum('pending','approved','paid','rejected') DEFAULT 'pending',
  `approvedBy` int(11) DEFAULT NULL,
  `approvedDate` datetime DEFAULT NULL,
  `paidOn` date DEFAULT NULL,
  `paymentRef` varchar(100) DEFAULT NULL,
  `remarks` text DEFAULT NULL,
  `createdAt` datetime DEFAULT current_timestamp(),
  `status` tinyint(1) DEFAULT 1,
  PRIMARY KEY (`encashmentID`),
  KEY `idx_user` (`userID`),
  KEY `idx_fy` (`financialYear`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
