DROP TABLE IF EXISTS `mx_leave_type`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8mb4 */;
CREATE TABLE `mx_leave_type` (
  `leaveTypeID` int(11) NOT NULL AUTO_INCREMENT,
  `leaveTypeName` varchar(255) DEFAULT NULL,
  `allotedLeave` int(11) DEFAULT 0,
  `leaveSubType` int(11) NOT NULL DEFAULT 0 COMMENT '0=''regular leave'',1=''special leave''',
  `leaveMinDuration` int(11) DEFAULT 0,
  `leaveElegibleDuration` int(11) DEFAULT 0,
  `status` tinyint(1) NOT NULL DEFAULT 1,
  `annualEntitlement` int(11) DEFAULT 0 COMMENT 'Default annual leave days',
  `isCarryForward` tinyint(1) DEFAULT 0 COMMENT '1=Can carry forward, 0=Lapses',
  `maxCarryForward` int(11) DEFAULT 0 COMMENT 'Max days that can be carried forward',
  `maxAccumulation` int(11) DEFAULT 0 COMMENT 'Max total days that can accumulate',
  `isEncashable` tinyint(1) DEFAULT 0 COMMENT '1=Can encash, 0=Cannot',
  `encashmentRate` decimal(5,2) DEFAULT 100.00 COMMENT 'Encashment rate (% of basic salary)',
  `isPaidLeave` tinyint(1) DEFAULT 1 COMMENT '1=Paid, 0=Unpaid',
  `countsAsPresent` tinyint(1) DEFAULT 0,
  `requiresApproval` tinyint(1) DEFAULT 1 COMMENT '1=Needs manager approval',
  `requiresDocument` tinyint(1) DEFAULT 0 COMMENT '1=Requires supporting document',
  `documentAfterDays` int(11) DEFAULT 2 COMMENT 'Document required if leave > X days',
  `applicableGender` enum('all','male','female') DEFAULT 'all',
  `minServiceDays` int(11) DEFAULT 0 COMMENT 'Min days of service required to avail',
  `accrualType` enum('yearly','monthly','on_joining') DEFAULT 'yearly' COMMENT 'How leave is credited',
  `accrualRate` decimal(5,2) DEFAULT 0.00 COMMENT 'For monthly accrual: days per month',
  `colorCode` varchar(10) DEFAULT '#3498db' COMMENT 'UI display color',
  `sortOrder` int(11) DEFAULT 0,
  PRIMARY KEY (`leaveTypeID`)
) ENGINE=InnoDB AUTO_INCREMENT=19 DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;
