CREATE TABLE `mx_leave_yearly_reset_log` (
  `resetLogID` int(11) NOT NULL AUTO_INCREMENT,
  `userID` int(11) NOT NULL,
  `leaveTypeID` int(11) NOT NULL,
  `fromFinancialYear` varchar(10) NOT NULL,
  `toFinancialYear` varchar(10) NOT NULL,
  `previousBalance` decimal(5,2) DEFAULT 0.00,
  `carryForwardAmount` decimal(5,2) DEFAULT 0.00,
  `lapsedAmount` decimal(5,2) DEFAULT 0.00,
  `encashedAmount` decimal(5,2) DEFAULT 0.00,
  `newYearCredit` decimal(5,2) DEFAULT 0.00,
  `newOpeningBalance` decimal(5,2) DEFAULT 0.00,
  `resetDate` datetime DEFAULT current_timestamp(),
  `processedBy` int(11) DEFAULT NULL COMMENT 'NULL if auto, userID if manual',
  PRIMARY KEY (`resetLogID`),
  KEY `idx_user_fy` (`userID`,`fromFinancialYear`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
