DROP TABLE IF EXISTS `mx_motor_specification`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8mb4 */;
CREATE TABLE `mx_motor_specification` (
  `motorSpecID` int(11) NOT NULL AUTO_INCREMENT,
  `motorID` int(11) NOT NULL,
  `specTitle` varchar(255) DEFAULT NULL,
  `specOutput` varchar(100) DEFAULT NULL,
  `specVoltage` varchar(100) DEFAULT NULL,
  `specFrameSize` varchar(100) DEFAULT NULL,
  `specStandard` varchar(255) DEFAULT NULL,
  `specPoles` varchar(50) DEFAULT NULL,
  `specFrequency` varchar(50) DEFAULT NULL,
  `status` int(11) DEFAULT 1,
  `createdDate` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`motorSpecID`),
  KEY `idx_motorID` (`motorID`),
  KEY `idx_status` (`status`),
  CONSTRAINT `mx_motor_specification_ibfk_1` FOREIGN KEY (`motorID`) REFERENCES `mx_motor` (`motorID`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=103 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
