INSERT INTO `mx_page` VALUES (1,'en',NULL,'footer','Footer',NULL,NULL,'<div class=\"site-footer__top\">\n <div class=\"row\">\n <div class=\"col-xl-5 col-lg-6 col-md-6 wow fadeInUp\" data-wow-delay=\"200ms\">\n <div class=\"footer-widget__column footer-widget__links\">\n <div class=\"footer-widget__title-box\">\n <h4 class=\"footer-widget__title\">Ahmedabad (Gujarat) Office</h4>\n </div>\n <ul class=\"footer-widget__links-list list-unstyled\">\n <li><i class=\"fa fa-map-marker-alt\"></i>F-10, Satyam Complex, Near Prerna Tirth Derasar, <br /> Jodhpurgam, Satellite, Ahmedabad - 380015</li>\n <li><i class=\"fa fa-phone-alt\"></i><a href=\"tel:079-26929806\">079-26929806</a> | <a href=\"tel:079-26929807\">079-26929807</a> | <a href=\"tel:079-26923834\">079-26923834</a> | <a href=\"tel:079-40095667\">079-40095667</a></li>\n <li><i class=\"fa fa-fax\"></i><a href=\"tel:079-26929806\">079-26929806</a> | <a href=\"tel:079-26929807\">079-26929807</a></li>\n <li><i class=\"fa fa-envelope\"></i><a href=\"mailto:besahmedabad@gmail.com\">besahmedabad@gmail.com</a></li>\n <li><i class=\"fa fa-mobile-alt\"></i><a href=\"tel:+919825014977\">+919825014977</a></li>\n </ul>\n </div>\n </div>\n <div class=\"col-xl-5 col-lg-6 col-md-6 wow fadeInUp\" data-wow-delay=\"200ms\">\n <div class=\"footer-widget__column footer-widget__links\">\n <div class=\"footer-widget__title-box\">\n <h4 class=\"footer-widget__title\">Mumbai ( Maharashtra ) Office</h4>\n </div>\n <ul class=\"footer-widget__links-list list-unstyled\">\n <li><i class=\"fa fa-map-marker-alt\"></i>Bombay Engineering Syndicate, 2nd Floor, Modern House, Dr. V.B. Gandhi Marg, Kala Ghoda, Fort, Mumbai, Maharashtra 400001</li>\n <li><i class=\"fa fa-phone-alt\"></i><a href=\"tel:022-22842982\">022-22842982</a> | <a href=\"tel:022-22844691\">022-22844691</a> | <a href=\"tel:022-22046474\">022-22046474</a></li>\n <li><i class=\"fa fa-envelope\"></i><a href=\"mailto:besyndicate@gmail.com\">besyndicate@gmail.com</a></li>\n <li><i class=\"fa fa-mobile-alt\"></i><a href=\"tel:+919324706905\">+91 93247 06905</a></li>\n </ul>\n </div>\n </div>\n <div class=\"col-xl-2 col-lg-6 col-md-6 wow fadeInUp\" data-wow-delay=\"400ms\">\n <div class=\"footer-widget__column footer-widget__social-box\">\n <div class=\"site-footer__social\">\n <a href=\"#\"><i class=\"fab fa-twitter\"></i></a>\n <a href=\"#\"><i class=\"fab fa-facebook\"></i></a>\n <a href=\"#\"><i class=\"fab fa-pinterest-p\"></i></a>\n <a href=\"#\"><i class=\"fab fa-instagram\"></i></a>\n </div>\n </div>\n </div>\n </div>\n </div>\n <div class=\"site-footer__bottom\">\n <div class=\"row\">\n <div class=\"col-xl-12\">\n <div class=\"site-footer__bottom-inner\">\n <p class=\"site-footer__bottom-text\">© 2023 Bombay Engineering Syndicate. All Rights Reserved.</p>\n <!-- <ul class=\"list-unstyled site-footer__bottom-menu\">\n <li><a href=\"#\">Help</a></li>\n <li><a href=\"#\">Privacy Policy</a></li>\n -->\n </div>\n </div>\n </div>\n </div>',NULL,NULL,0,0),(2,'en',NULL,'about-us','About us',NULL,'<div class=\"container\" style=\"margin-top: 50px; padding-top: 30px;\">\n <h3>Our Presence and Capabilities</h3>\n <p>BES operates from Mumbai (Maharashtra) and Ahmedabad (Gujarat), serving a diverse client base that includes industries, OEMs, EPC contractors, project consultants, infrastructure companies, and retail customers.</p>\n <br />\n <p>We are equipped to handle large-scale project enquiries, complex engineering specifications, and day-to-day retail requirements with equal precision.</p>\n <br />\n <p>Our team is experienced in working with major consultants and EPC firms such as:</p>\n <ul>\n <li>EIL</li>\n <li>TOYO</li>\n <li>L&amp;T</li>\n <li>Lurgi</li>\n <li>Mecons</li>\n <li>Foster Wheeler</li>\n <li>Jacobs</li>\n <li>BHEL</li>\n <li>NTPC</li>\n <li>NPC</li>\n <li>and more</li>\n </ul>\n <br />\n <p>We provide complete documentation support, including pre-tendering guidance, spec-matching, technical datasheets, GA drawings, QAP, inspection coordination, and post-order execution.</p>\n <br /><br />\n <h3>Our Product Range</h3>\n <p>BES offers one of the widest ranges of LV &amp; HV Industrial Motors in India:</p>\n <br />\n <p><strong><span style=\"color:#3498db;\">Types of Motors</span></strong></p>\n <ul>\n <li>LT / HT Industrial Motors</li>\n <li>IE2 / IE3 / IE4 High-Efficiency Motors</li>\n <li>Hazardous Area Motors</li>\n <li>Increased Safety Ex “e”</li>\n <li>Non-Sparking Ex “n”</li>\n <li>Flame Proof Ex “d” (Gas Group IIA / IIB / IIC)</li>\n <li>Crane Duty Motors</li>\n <li>Ginning Motors</li>\n <li>Textile Motors</li>\n <li>Brake Motors</li>\n <li>Roller Table Motors</li>\n <li>Cooling Tower Motors</li>\n <li>Energy Efficient Motors</li>\n <li>Pressure Booster Pump Motors</li>\n <li>Special Application Motors for OEMs</li>\n </ul>\n <br />\n <p><strong><span style=\"color:#3498db;\">Drives, Controls &amp; Energy-Saving Solutions</span></strong></p>\n <ul>\n <li>AC Variable Frequency Drives (VFDs)</li>\n <li>Soft Starters</li>\n <li>Motor Protection Devices &amp; Starters</li>\n <li>IE3/IE4 energy-efficient upgrades</li>\n <li>Customized power-saving solutions for HVAC, water supply, and industrial processes</li>\n </ul>\n <br /><br />\n <h3>Substitutes for Imported Motors</h3>\n <p>We specialize in providing reliable replacements for imported NEMA and IEC frame motors, offering:</p>\n <ul>\n <li>Faster delivery</li>\n <li>Lower cost of ownership</li>\n <li>Local service support</li>\n <li>High-efficiency equivalents to global brands</li>\n </ul>\n <br />\n <p>Our technical expertise ensures accurate frame matching, RPM matching, shaft dimensions, mounting compatibility, and performance equivalence.</p>\n <br /><br />\n <h3>Industries We Serve</h3>\n <p>Our products cater to a wide spectrum of industries:</p>\n <ul>\n <li>Oil &amp; Gas</li>\n <li>Petrochemicals &amp; Chemicals</li>\n <li>Pharmaceuticals</li>\n <li>Textiles</li>\n <li>Steel &amp; Metal Processing</li>\n <li>Infrastructure &amp; Construction</li>\n <li>Water Supply &amp; Sewage</li>\n <li>HVAC &amp; Building Utilities</li>\n <li>Machine Manufacturers (OEMs)</li>\n <li>Agriculture &amp; Irrigation</li>\n <li>Paper &amp; Pulp</li>\n </ul>\n <br />\n <p>BES is trusted by both large enterprises and small businesses for providing reliable, high-quality motors with assured performance.</p>\n <br /><br />\n <h3>Why Clients Trust BES</h3>\n <ul>\n <li>✔ 65+ years of industry experience</li>\n <li>✔ Only genuine and certified CG / Crompton products</li>\n <li>✔ Technical support for sizing, selection, and troubleshooting</li>\n <li>✔ Prompt service, fast response times, and transparent communication</li>\n <li>✔ Extensive ready stock for fast delivery</li>\n <li>✔ Custom-engineered solutions for critical applications</li>\n <li>✔ End-to-end project support (tendering to commissioning)</li>\n </ul>\n <br />\n <p>Our goal is to provide the most suitable and cost-effective solution for every customer requirement—ensuring long-term reliability, energy savings, and complete customer satisfaction.</p>\n</div>','<div class=\"col-md-6\">\n<div class=\"about-one__right wow fadeInRight\" data-wow-delay=\"500ms\" data-wow-duration=\"1500ms\">\n<div class=\"section-title text-left\"><span class=\"section-title__tagline\">about us</span>\n<h2 class=\"section-title__title\">Company Profile</h2>\n</div>\n<p data-end=\"268\" data-start=\"103\"><strong data-end=\"221\" data-start=\"103\">Authorized Channel Partners of CG Power & Industrial Solutions Ltd. and Crompton Greaves Consumer Electricals Ltd.</strong><br data-end=\"224\" data-start=\"221\" />\n<strong data-end=\"268\" data-start=\"224\">Since 1957 — The Rotating Machine People</strong></p>\n<p data-end=\"597\" data-start=\"270\">Bombay Engineering Syndicate (BES) is one of India’s oldest and most trusted suppliers of <strong data-end=\"437\" data-start=\"360\">Electric Motors, Industrial Drives, and Energy-Efficient Motion Solutions</strong>. Established in 1957, we have over <strong data-end=\"498\" data-start=\"473\">65 years of expertise</strong> as an authorized channel partner for <strong data-end=\"548\" data-start=\"536\">CG Power</strong> and <strong data-end=\"594\" data-start=\"553\">Crompton Greaves Consumer Electricals</strong>.</p>\n<p data-end=\"754\" data-start=\"599\"></p>\n</div>\n</div>','adobestock_107220281.webp','page-tpl',1,0),(3,'en',NULL,'contact-us','Contact Us',NULL,'<div class=\"col-xl-4 col-lg-5\">\n<div class=\"contact-page__left\">\n<div class=\"section-title text-left\"><span class=\"section-title__tagline\">Contact us</span>\n<h2 class=\"section-title__title\">Send a Message</h2>\n</div>\n<p class=\"contact-page__text\">Have a Query? We Will Contact you within 24 Hours!</p>\n</div>\n</div>','<div class=\"container\">\n<div class=\"section-title text-center\"><span class=\"section-title__tagline\">Locations</span>\n<h2 class=\"section-title__title\">Bombay Engineering Syndicate</h2>\n</div>\n<div class=\"row\">\n<div class=\"col-xl-6 col-lg-6 col-md-12\">\n<div class=\"spa-center-three__single\">\n<h3 class=\"spa-center-three__title\">Ahmedabad (Gujarat) Office</h3>\n<ul class=\"contact-links-list list-unstyled\">\n <li>Office No. 611, 612,Ratnanjali Solitaire,Near Sachet - 4,<br />\n Prerna Tirth Derasar Road, Jodhpurgam, Satellite, Ahmedabad - 380015</li>\n <li><a href=\"tel:079-26929806\">079-26929806</a> | <a href=\"tel:079-26929807\">079-26929807</a> | <a href=\"tel:079-26923834\">079-26923834</a> | <a href=\"tel:079-40095667\">079-40095667</a></li>\n <li><a href=\"tel:079-26929806\">079-26929806</a> | <a href=\"tel:079-26929807\">079-26929807</a></li>\n <li><a href=\"mailto:besahmedabad@gmail.com\">besahmedabad@gmail.com</a></li>\n <li><a href=\"tel:+919825014977\">+919825014977</a></li>\n</ul>\n<!-- <div class=\"spa-center-three__contact\">\n <a href=\"mailto:needhelp@company.com\">needhelp@company.com</a>\n <a href=\"tel:8889990000\">888 999 0000</a>\n </div> --></div>\n</div>\n<div class=\"col-xl-6 col-lg-6 col-md-12\">\n<div class=\"spa-center-three__single\">\n<h3 class=\"spa-center-three__title\">Mumbai ( Maharashtra ) Office</h3>\n<ul class=\"contact-links-list list-unstyled\">\n <li>Bombay Engineering Syndicate, 2nd Floor, Modern House, Dr. V.B. Gandhi Marg, Kala Ghoda, Fort, Mumbai, Maharashtra 400001</li>\n <li><a href=\"tel:022-22842982\">022-22842982</a> | <a href=\"tel:022-22844691\">022-22844691</a> | <a href=\"tel:022-22046474\">022-22046474</a></li>\n <li><a href=\"mailto:besyndicate@gmail.com\">besyndicate@gmail.com</a></li>\n <li><a href=\"tel:+919324706905\">+91 93247 06905</a></li>\n</ul>\n</div>\n</div>\n</div>',NULL,'contact-us-tpl',1,0),(4,'en',NULL,'financials','Financials',NULL,NULL,NULL,NULL,NULL,1,0),(5,'en',NULL,'testing-page','testing page',NULL,NULL,'<p>testing page</p>',NULL,'page-tpl',0,0),(6,'en',NULL,'terms-conditions','Terms & Conditions',NULL,NULL,'<p class=\"last-updated\">Last updated: February 23, 2026</p>\n\n<p>Welcome to <a href=\"https://www.bombayengg.net\">www.bombayengg.net</a>, operated by Bombay Engineering Syndicate (\"we\", \"us\", or \"our\"). By accessing or using this website, you agree to be bound by the following Terms and Conditions. If you do not agree, please do not use this website.</p>\n\n<h2>1. About Us</h2>\n<p>Bombay Engineering Syndicate is an authorized channel partner and distributor of industrial electric motors, pumps, and related equipment. We are authorized dealers for CG Power and Industrial Solutions Limited, Crompton Greaves Consumer Electricals Ltd, and Kirloskar Brothers Limited, among others. Established in 1957, we operate from offices in Mumbai and Ahmedabad.</p>\n\n<h2>2. Use of Website</h2>\n<ul>\n<li>This website is intended for informational purposes and to facilitate product inquiries for industrial motors, pumps, and related equipment.</li>\n<li>You agree to use this website only for lawful purposes and in a manner that does not infringe upon or restrict the rights of others.</li>\n<li>You must not misuse this website by knowingly introducing viruses, trojans, or other malicious or technologically harmful material.</li>\n<li>Unauthorized use of this website may give rise to a claim for damages and/or be a criminal offence under Indian law.</li>\n</ul>\n\n<h2>3. Product Information</h2>\n<ul>\n<li>We make every effort to display product information, specifications, and images as accurately as possible.</li>\n<li>Product specifications (kW ratings, voltages, dimensions, etc.) are provided for reference and may vary. Always confirm exact specifications with our sales team before placing an order.</li>\n<li>Product images are representative. Actual products may differ slightly in appearance.</li>\n<li>Product availability is subject to stock and manufacturer supply. We reserve the right to discontinue any product without prior notice.</li>\n<li>Prices displayed on this website, if any, are indicative and subject to change without notice. Final pricing will be confirmed in our official quotation.</li>\n</ul>\n\n<h2>4. Inquiries and Quotations</h2>\n<ul>\n<li>Submitting a product inquiry or contact form does not constitute an order or a binding agreement.</li>\n<li>Quotations provided by us are valid for the period specified in the quotation document. If no period is specified, quotations are valid for 15 days from the date of issue.</li>\n<li>A binding contract is formed only upon our written confirmation of your order and receipt of applicable payment or credit terms.</li>\n<li>All orders are subject to product availability and our acceptance.</li>\n</ul>\n\n<h2>5. Intellectual Property</h2>\n<ul>\n<li>All content on this website — including text, images, logos, graphics, product data, and design — is the property of Bombay Engineering Syndicate or our authorized brand partners (CG Power, Crompton, Kirloskar) and is protected under Indian intellectual property laws.</li>\n<li>You may not reproduce, distribute, modify, or republish any content from this website without our prior written consent.</li>\n<li>Brand names, logos, and trademarks of CG Power and Industrial Solutions Limited, Crompton Greaves Consumer Electricals Ltd, Kirloskar Brothers Limited, and other manufacturers remain the property of their respective owners.</li>\n</ul>\n\n<h2>6. Warranty and Liability</h2>\n<ul>\n<li>Products sold by us carry the manufacturer\'s warranty as per the respective brand\'s warranty policy. We do not provide any additional warranty beyond the manufacturer\'s warranty unless explicitly stated in writing.</li>\n<li>This website and its content are provided \"as is\" without warranties of any kind, express or implied.</li>\n<li>We shall not be liable for any indirect, incidental, special, or consequential damages arising from the use of this website or reliance on any information provided herein.</li>\n<li>Our total liability, if any, shall not exceed the value of the specific product or service in question.</li>\n</ul>\n\n<h2>7. Payment Terms</h2>\n<ul>\n<li>Payment terms will be specified in individual quotations and order confirmations.</li>\n<li>Unless otherwise agreed in writing, payment is due as per the terms stated on the invoice.</li>\n<li>Late payments may attract interest as per applicable commercial rates.</li>\n</ul>\n\n<h2>8. Delivery and Shipping</h2>\n<ul>\n<li>Delivery timelines provided are estimates and may vary depending on product availability and logistics.</li>\n<li>Risk of loss and damage passes to the buyer upon dispatch from our warehouse or the manufacturer\'s facility, as applicable.</li>\n<li>Any delivery-related claims must be reported within 48 hours of receipt of goods.</li>\n</ul>\n\n<h2>9. Returns and Cancellations</h2>\n<ul>\n<li>Returns are accepted only for manufacturing defects, subject to the manufacturer\'s return policy.</li>\n<li>Custom-ordered or made-to-order products are non-returnable and non-cancellable.</li>\n<li>Any return or cancellation request must be communicated in writing to our office.</li>\n</ul>\n\n<h2>10. WhatsApp Business Communications</h2>\n<ul>\n<li>By initiating a conversation with us on WhatsApp or opting into WhatsApp notifications, you consent to receiving business-related messages including order updates, delivery notifications, and inquiry responses.</li>\n<li>You may opt out at any time by messaging \"STOP\" or contacting our office.</li>\n<li>WhatsApp communications are subject to our <a href=\"/privacy-policy/\">Privacy Policy</a> and <a href=\"https://www.whatsapp.com/legal/terms-of-service\" target=\"_blank\" rel=\"noopener\">WhatsApp\'s Terms of Service</a>.</li>\n</ul>\n\n<h2>11. HRMS Portal (Employees Only)</h2>\n<ul>\n<li>The HRMS portal is exclusively for authorized employees of Bombay Engineering Syndicate.</li>\n<li>Employees are responsible for maintaining the confidentiality of their login credentials.</li>\n<li>Any misuse of the HRMS portal may result in disciplinary action.</li>\n<li>Attendance, leave, and salary data in the HRMS is governed by company HR policies and applicable Indian labor laws.</li>\n</ul>\n\n<h2>12. Third-Party Links</h2>\n<p>This website may contain links to third-party websites. We have no control over and are not responsible for the content, privacy policies, or practices of any third-party websites. Visiting such links is at your own risk.</p>\n\n<h2>13. Governing Law and Jurisdiction</h2>\n<ul>\n<li>These Terms and Conditions are governed by and construed in accordance with the laws of India.</li>\n<li>Any disputes arising from the use of this website or our services shall be subject to the exclusive jurisdiction of the courts in Mumbai, Maharashtra.</li>\n</ul>\n\n<h2>14. Changes to These Terms</h2>\n<p>We reserve the right to update or modify these Terms and Conditions at any time without prior notice. Changes will be posted on this page with an updated date. Your continued use of this website after any changes constitutes acceptance of the revised terms.</p>\n\n<h2>15. Contact Us</h2>\n\n<div class=\"contact-box\">\n<h3>Bombay Engineering Syndicate</h3>\n<p><strong>Mumbai Office (Registered):</strong><br>\n2nd Floor, Modern House, Dr. V.B. Gandhi Marg, Kala Ghoda, Fort, Mumbai, Maharashtra 400001<br>\nPhone: <a href=\"tel:+919324706905\">+91 93247 06905</a><br>\nEmail: <a href=\"mailto:besyndicate@gmail.com\">besyndicate@gmail.com</a></p>\n\n<p><strong>Ahmedabad Office:</strong><br>\nOffice No. 611-612, Ratnanjali Solitaire, Satellite, Ahmedabad - 380015<br>\nPhone: <a href=\"tel:+919825014977\">+91 98250 14977</a><br>\nEmail: <a href=\"mailto:besahmedabad@gmail.com\">besahmedabad@gmail.com</a></p>\n</div>',NULL,'privacy-policy-tpl',1,0),(7,NULL,NULL,'service','Support','Customer Support','<h3>Important Notice</h3>\n<p><strong>Bombay Engineering Syndicate</strong> is an authorized distributor and does not directly undertake servicing or repairs. However, we are happy to assist you in connecting with the manufacturer\'s service network. For the best and fastest support, we recommend contacting the manufacturer\'s helpline directly.</p>','<h1 class=\"service-intro__title\" id=\"support-title\">Service & Support Assistance</h1>\n<p class=\"service-intro__subtitle\">Get the help you need for your pumps and motors. We guide you to the right support channels for quick resolution.</p>',NULL,'service-tpl',1,0),(8,NULL,NULL,'pumps-in-mumbai','Pumps in Mumbai - Industrial & Submersible Pump Supplier','Industrial & Submersible Pumps in Mumbai','','',NULL,'pumps-in-mumbai-tpl',1,0),(9,NULL,NULL,'motors-in-mumbai','Motors in Mumbai - Industrial Electric Motor Supplier','Industrial Electric Motors in Mumbai','','',NULL,'motors-in-mumbai-tpl',1,0),(10,NULL,NULL,'pumps-in-ahmedabad','Pumps in Ahmedabad - Industrial & Submersible Pump Supplier','Industrial & Submersible Pumps in Ahmedabad','','',NULL,'pumps-in-ahmedabad-tpl',1,0),(11,NULL,NULL,'motors-in-ahmedabad','Motors in Ahmedabad - Industrial Electric Motor Supplier','Industrial Electric Motors in Ahmedabad','','',NULL,'motors-in-ahmedabad-tpl',1,0),(12,NULL,NULL,'privacy-policy','Privacy Policy','Your Privacy Matters','','<p class=\"last-updated\">Last updated: February 23, 2026</p>\n\n<p>Bombay Engineering Syndicate (\"we\", \"us\", or \"our\") operates the website <a href=\"https://www.bombayengg.net\">www.bombayengg.net</a> and associated services. This Privacy Policy explains how we collect, use, disclose, and safeguard your information when you visit our website, use our services, or communicate with us through any channel including WhatsApp Business.</p>\n\n<p>By using our website or services, you agree to the collection and use of information in accordance with this policy.</p>\n\n<h2>1. Information We Collect</h2>\n\n<h3>1.1 Information You Provide</h3>\n<ul>\n<li><strong>Contact Form Submissions:</strong> Name, email address, mobile number, and message content when you use our Contact Us form.</li>\n<li><strong>Product Inquiry Forms:</strong> Name, email, phone number, company name, and product requirements when you submit pump or motor inquiry forms.</li>\n<li><strong>WhatsApp Communications:</strong> Phone number and message content when you communicate with us via WhatsApp Business.</li>\n<li><strong>Business Correspondence:</strong> Any information you voluntarily provide via email, phone, or in-person meetings.</li>\n</ul>\n\n<h3>1.2 Information Collected Automatically</h3>\n<ul>\n<li><strong>Device Information:</strong> Browser type, operating system, device type, and screen resolution.</li>\n<li><strong>Usage Data:</strong> Pages visited, time spent on pages, referring URLs, and navigation patterns.</li>\n<li><strong>IP Address:</strong> Your internet protocol address for security and analytics purposes.</li>\n<li><strong>Cookies:</strong> Small data files stored on your device to improve your browsing experience (see Section 5).</li>\n</ul>\n\n<h3>1.3 Employee Information (HRMS)</h3>\n<p>For employees of Bombay Engineering Syndicate, our Human Resource Management System (HRMS) collects and processes:</p>\n<ul>\n<li>Personal identification details (name, contact information, emergency contacts)</li>\n<li>Employment records (designation, department, joining date)</li>\n<li>Attendance and biometric data (clock-in/out times via CAMS biometric devices)</li>\n<li>Leave records and balances</li>\n<li>Salary and compensation information</li>\n<li>WhatsApp number for HRMS notifications (if opted in)</li>\n</ul>\n\n<h2>2. How We Use Your Information</h2>\n\n<p>We use the collected information for the following purposes:</p>\n<ul>\n<li><strong>Respond to Inquiries:</strong> To reply to your product inquiries, contact form submissions, and service requests.</li>\n<li><strong>Product Quotations:</strong> To prepare and send quotations for motors, pumps, and related industrial equipment.</li>\n<li><strong>WhatsApp Notifications:</strong> To send order updates, delivery notifications, and respond to your queries via WhatsApp Business (only if you initiate contact or opt in).</li>\n<li><strong>Website Improvement:</strong> To analyze usage patterns and improve our website content, navigation, and user experience.</li>\n<li><strong>Security:</strong> To protect our website from fraud, unauthorized access, and other security threats.</li>\n<li><strong>Legal Compliance:</strong> To comply with applicable Indian laws and regulations, including the Digital Personal Data Protection Act, 2023.</li>\n<li><strong>Employee Management:</strong> To manage attendance, leave, payroll, and HR operations for our employees through our HRMS.</li>\n</ul>\n\n<h2>3. WhatsApp Business Communications</h2>\n\n<p>We use the WhatsApp Business API to communicate with customers and employees. By messaging us on WhatsApp or opting into WhatsApp notifications:</p>\n<ul>\n<li>Your phone number and chat content are processed through Meta\'s WhatsApp Business Platform.</li>\n<li>We may send you transactional messages (order confirmations, delivery updates) and respond to your inquiries.</li>\n<li>For employees: HRMS notifications (attendance alerts, leave approvals, salary slip availability) may be sent via WhatsApp if you opt in.</li>\n<li>You can opt out of WhatsApp notifications at any time by messaging \"STOP\" or contacting our office.</li>\n<li>WhatsApp communications are subject to <a href=\"https://www.whatsapp.com/legal/privacy-policy\" target=\"_blank\" rel=\"noopener\">WhatsApp\'s own Privacy Policy</a>.</li>\n</ul>\n\n<h2>4. Information Sharing and Disclosure</h2>\n\n<p>We do not sell, trade, or rent your personal information to third parties. We may share your information only in the following circumstances:</p>\n<ul>\n<li><strong>Service Providers:</strong> With trusted third-party service providers who assist us in operating our website, conducting our business, or servicing you (e.g., web hosting, email services, WhatsApp Business API providers), subject to confidentiality agreements.</li>\n<li><strong>Business Partners:</strong> With our authorized principals (CG Power and Industrial Solutions Limited, Crompton Greaves Consumer Electricals Ltd, Kirloskar Brothers Limited) only to the extent necessary to fulfill your product inquiries and orders.</li>\n<li><strong>Legal Requirements:</strong> When required by law, court order, or governmental regulation.</li>\n<li><strong>Business Protection:</strong> To protect the rights, property, or safety of Bombay Engineering Syndicate, our employees, or others.</li>\n</ul>\n\n<h2>5. Cookies and Tracking Technologies</h2>\n\n<p>Our website uses cookies and similar technologies to:</p>\n<ul>\n<li>Remember your preferences and settings</li>\n<li>Understand how you use our website (via Google Analytics)</li>\n<li>Provide Google reCAPTCHA protection on our forms</li>\n<li>Enable embedded Google Maps functionality</li>\n</ul>\n\n<p>You can control cookies through your browser settings. Disabling cookies may affect some website functionality.</p>\n\n<h3>Third-Party Services</h3>\n<ul>\n<li><strong>Google Analytics:</strong> We use Google Analytics to understand website traffic. Google\'s privacy policy is available at <a href=\"https://policies.google.com/privacy\" target=\"_blank\" rel=\"noopener\">policies.google.com/privacy</a>.</li>\n<li><strong>Google reCAPTCHA:</strong> Our forms use Google reCAPTCHA to prevent spam. This service may collect hardware and software information.</li>\n<li><strong>Google Maps:</strong> Embedded maps on our website are subject to Google\'s privacy policy.</li>\n</ul>\n\n<h2>6. Data Security</h2>\n\n<p>We implement appropriate technical and organizational security measures to protect your personal information, including:</p>\n<ul>\n<li>SSL/TLS encryption (HTTPS) for all data transmitted to and from our website</li>\n<li>Secure database storage with access controls</li>\n<li>Regular security monitoring and updates</li>\n<li>Restricted access to personal data on a need-to-know basis</li>\n</ul>\n\n<p>While we strive to protect your personal information, no method of transmission over the Internet is 100% secure. We cannot guarantee absolute security.</p>\n\n<h2>7. Data Retention</h2>\n\n<ul>\n<li><strong>Contact Inquiries:</strong> Retained for up to 3 years for follow-up and business relationship purposes.</li>\n<li><strong>Website Analytics:</strong> Aggregated data retained for up to 26 months.</li>\n<li><strong>Employee Records:</strong> Retained as per Indian labor law requirements and company policy.</li>\n<li><strong>WhatsApp Messages:</strong> Business-related messages retained as per our record-keeping policy; you may request deletion of your chat data.</li>\n</ul>\n\n<h2>8. Your Rights</h2>\n\n<p>Under the Digital Personal Data Protection Act, 2023 (DPDPA) and applicable laws, you have the right to:</p>\n<ul>\n<li><strong>Access:</strong> Request information about what personal data we hold about you.</li>\n<li><strong>Correction:</strong> Request correction of inaccurate or incomplete personal data.</li>\n<li><strong>Erasure:</strong> Request deletion of your personal data, subject to legal retention requirements.</li>\n<li><strong>Withdraw Consent:</strong> Withdraw your consent for data processing at any time (this will not affect processing done before withdrawal).</li>\n<li><strong>Grievance Redressal:</strong> Lodge a complaint regarding the processing of your personal data.</li>\n</ul>\n\n<p>To exercise any of these rights, please contact us using the details provided below.</p>\n\n<h2>9. Children\'s Privacy</h2>\n\n<p>Our website and services are not directed at individuals under the age of 18. We do not knowingly collect personal information from children. If you believe we have inadvertently collected such information, please contact us immediately.</p>\n\n<h2>10. Changes to This Policy</h2>\n\n<p>We may update this Privacy Policy from time to time. Any changes will be posted on this page with an updated \"Last updated\" date. We encourage you to review this policy periodically.</p>\n\n<h2>11. Contact Us</h2>\n\n<div class=\"contact-box\">\n<h3>Bombay Engineering Syndicate</h3>\n<p><strong>Mumbai Office (Registered):</strong><br>\n2nd Floor, Modern House, Dr. V.B. Gandhi Marg, Kala Ghoda, Fort, Mumbai, Maharashtra 400001<br>\nPhone: <a href=\"tel:+919324706905\">+91 93247 06905</a><br>\nEmail: <a href=\"mailto:besyndicate@gmail.com\">besyndicate@gmail.com</a></p>\n\n<p><strong>Ahmedabad Office:</strong><br>\nOffice No. 611-612, Ratnanjali Solitaire, Satellite, Ahmedabad - 380015<br>\nPhone: <a href=\"tel:+919825014977\">+91 98250 14977</a><br>\nEmail: <a href=\"mailto:besahmedabad@gmail.com\">besahmedabad@gmail.com</a></p>\n\n<p>For privacy-related queries or to exercise your data protection rights, please email us at <a href=\"mailto:besyndicate@gmail.com\">besyndicate@gmail.com</a> with the subject line \"Privacy Policy Inquiry\".</p>\n</div>',NULL,'privacy-policy-tpl',1,0),(13,'en',NULL,'mumbai','Mumbai Office',NULL,NULL,NULL,NULL,'mumbai-tpl',1,0),(14,'en',NULL,'ahmedabad','Ahmedabad Office',NULL,NULL,NULL,NULL,'ahmedabad-tpl',1,0),(15,'en',NULL,'mumbai','Mumbai Office',NULL,NULL,NULL,NULL,'mumbai-tpl',0,0),(16,'en',NULL,'ahmedabad','Ahmedabad Office',NULL,NULL,NULL,NULL,'ahmedabad-tpl',0,0),(17,'en',NULL,'mumbai','Mumbai Office',NULL,NULL,NULL,NULL,'mumbai-tpl',0,0),(18,'en',NULL,'ahmedabad','Ahmedabad Office',NULL,NULL,NULL,NULL,'ahmedabad-tpl',0,0),(19,NULL,NULL,'pumps-in-fort','Pumps in Fort - Water Pump Dealer in Fort Mumbai',NULL,NULL,NULL,NULL,'pumps-in-fort-tpl',1,0),(20,NULL,NULL,'motors-in-fort','Motors in Fort - Electric Motor Dealer in Fort Mumbai',NULL,NULL,NULL,NULL,'motors-in-fort-tpl',1,0),(21,NULL,NULL,'pumps-in-satellite-ahmedabad','Pumps in Satellite Ahmedabad - Water Pump Dealer',NULL,NULL,NULL,NULL,'pumps-in-satellite-ahmedabad-tpl',1,0),(22,NULL,NULL,'motors-in-satellite-ahmedabad','Motors in Satellite Ahmedabad - Electric Motor Dealer',NULL,NULL,NULL,NULL,'motors-in-satellite-ahmedabad-tpl',1,0),(23,NULL,NULL,'crompton-motor-dealer-mumbai','Authorised CG Power & Crompton Greaves Motor Dealer in Mumbai','Authorised Motor Dealer, Distributor & Supplier in Mumbai','','',NULL,'crompton-motor-dealer-mumbai-tpl',1,0),(24,NULL,NULL,'vfd-ac-drive-dealer-mumbai','VFD & AC Drive Dealer in Mumbai | CG Emotron Authorised','Authorised CG Emotron VFD, AC Drive & Soft Starter Dealer in Mumbai','','',NULL,'vfd-ac-drive-dealer-mumbai-tpl',1,0),(25,NULL,NULL,'motors-in-pune','Motors in Pune - CG Crompton Industrial Motor Dealer & Supplier','Industrial Electric Motor Dealer, Distributor & Supplier for Pune & PCMC','','',NULL,'motors-in-pune-tpl',1,0),(26,NULL,NULL,'motors-in-nashik','Motors in Nashik - CG Crompton Industrial Motor Dealer & Supplier','Industrial Electric Motor Dealer for Nashik & North Maharashtra',NULL,NULL,NULL,'motors-in-nashik-tpl',1,0),(27,NULL,NULL,'motors-in-nagpur','Motors in Nagpur - CG Crompton HT & Industrial Motor Dealer','HT & I