DROP TABLE IF EXISTS `mx_product`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8mb4 */;
CREATE TABLE `mx_product` (
  `productID` int(11) NOT NULL AUTO_INCREMENT,
  `orgID` int(11) NOT NULL DEFAULT 0,
  `productTitle` varchar(255) DEFAULT NULL,
  `seoUri` varchar(255) DEFAULT NULL,
  `isSP` tinyint(4) NOT NULL DEFAULT 0,
  `isPP` tinyint(4) NOT NULL DEFAULT 0,
  `productDesc` text DEFAULT NULL,
  `productImg` varchar(255) DEFAULT NULL,
  `hsnID` int(11) DEFAULT 0,
  `unitID` int(11) DEFAULT 0,
  `categoryID` int(11) NOT NULL DEFAULT 0,
  `hsnCode` int(11) NOT NULL DEFAULT 0,
  `prodPurchaseRate` decimal(11,2) NOT NULL DEFAULT 0.00,
  `prodSaleRate` decimal(10,2) NOT NULL DEFAULT 0.00,
  `isSalesProduct` tinyint(1) NOT NULL DEFAULT 0,
  `qtyPurchased` decimal(11,2) NOT NULL DEFAULT 0.00,
  `qtySale` decimal(11,2) NOT NULL DEFAULT 0.00,
  `qtyBalance` decimal(11,2) NOT NULL DEFAULT 0.00,
  `qtyPurchaseReturn` decimal(10,2) NOT NULL DEFAULT 0.00,
  `qtySalesReturn` decimal(10,2) NOT NULL DEFAULT 0.00,
  `barcodeNo` varchar(100) DEFAULT NULL,
  `isActive` int(11) NOT NULL DEFAULT 1 COMMENT '1=Active,0=Deactive',
  `totalSaleQty` decimal(11,2) NOT NULL DEFAULT 0.00,
  `totalPurchaseQty` decimal(11,2) NOT NULL DEFAULT 0.00,
  `totalBalanceQty` decimal(11,2) NOT NULL DEFAULT 0.00,
  `status` tinyint(1) NOT NULL DEFAULT 1,
  PRIMARY KEY (`productID`)
) ENGINE=InnoDB AUTO_INCREMENT=77 DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

