CREATE TABLE `mx_product_inquiry` (
  `productInquiryID` int(11) NOT NULL AUTO_INCREMENT,
  `companyName` varchar(100) DEFAULT NULL,
  `userName` varchar(50) DEFAULT NULL,
  `userEmail` varchar(50) DEFAULT NULL,
  `userMobile` varchar(20) DEFAULT NULL,
  `makeOfMotor` varchar(100) DEFAULT NULL,
  `kw` varchar(40) DEFAULT NULL,
  `hp` varchar(20) DEFAULT NULL,
  `dutyID` int(11) NOT NULL DEFAULT 0,
  `rpm` varchar(20) DEFAULT NULL,
  `mountingID` int(11) NOT NULL DEFAULT 0,
  `typeOfMotorID` int(11) NOT NULL DEFAULT 0,
  `rotorTypeID` int(11) NOT NULL DEFAULT 0,
  `voltageID` int(11) DEFAULT 0,
  `frequencyID` int(11) NOT NULL DEFAULT 0,
  `efficiencyID` int(11) DEFAULT 0,
  `shaftExtensionID` int(11) NOT NULL DEFAULT 0,
  `expectedDeliveryTimeID` int(11) NOT NULL DEFAULT 0,
  `offerRequirementIs` varchar(5) DEFAULT NULL,
  `uploadFile` varchar(200) DEFAULT NULL,
  `requirementIsForRplc` tinyint(1) DEFAULT NULL,
  `makeOfMotorD` varchar(100) DEFAULT NULL,
  `kwD` varchar(40) DEFAULT NULL,
  `hpD` varchar(20) DEFAULT NULL,
  `rpmD` varchar(20) DEFAULT NULL,
  `mounting` varchar(50) DEFAULT NULL,
