--
-- Table structure for table `mx_x_admin_user`
--

DROP TABLE IF EXISTS `mx_x_admin_user`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8mb4 */;
CREATE TABLE `mx_x_admin_user` (
  `userID` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `employeeCode` varchar(20) DEFAULT NULL,
  `roleID` int(5) NOT NULL DEFAULT 0,
  `domainUri` varchar(150) DEFAULT NULL,
  `seoUri` varchar(150) DEFAULT NULL,
  `userName` varchar(100) DEFAULT NULL,
  `userPass` varchar(100) DEFAULT NULL,
  `userMobile` varchar(100) DEFAULT NULL,
  `userPin` varchar(5) DEFAULT NULL,
  `userEmail` varchar(100) DEFAULT NULL,
  `displayName` varchar(100) DEFAULT NULL,
  `imageName` varchar(255) DEFAULT NULL,
  `dateOfBirth` date DEFAULT NULL,
  `gender` enum('M','F','O') DEFAULT NULL,
  `bloodGroup` varchar(5) DEFAULT NULL,
  `emergencyContact` varchar(15) DEFAULT NULL,
  `whatsappNumber` varchar(15) DEFAULT NULL,
  `whatsappOptIn` tinyint(1) DEFAULT 0,
  `whatsappOptInDate` datetime DEFAULT NULL,
  `emergencyContactName` varchar(100) DEFAULT NULL,
  `emergencyContactRelation` varchar(50) DEFAULT NULL,
  `dateOfJoining` date DEFAULT NULL,
  `designation` varchar(100) DEFAULT NULL,
  `department` varchar(100) DEFAULT NULL,
  `employmentType` enum('permanent','contract','probation') DEFAULT 'permanent',
  `managerID` int(11) DEFAULT NULL,
  `bankName` varchar(100) DEFAULT NULL,
  `bankAccountNo` varchar(30) DEFAULT NULL,
  `bankIFSC` varchar(15) DEFAULT NULL,
  `bankBranch` varchar(100) DEFAULT NULL,
  `panNo` varchar(15) DEFAULT NULL,
  `aadhaarNo` varchar(15) DEFAULT NULL,
  `currentAddress` text DEFAULT NULL,
  `permanentAddress` text DEFAULT NULL,
  `biometricID` varchar(50) DEFAULT NULL,
  `autoAttendance` tinyint(1) DEFAULT 0 COMMENT '1=Auto mark present daily at shift time (no biometric)',
  `loginOTP` varchar(6) DEFAULT NULL,
  `otpExpiry` datetime DEFAULT NULL,
  `lastPortalLogin` datetime DEFAULT NULL,
  `dateOfExit` date DEFAULT NULL,
  `exitReason` text DEFAULT NULL,
  `dateLogin` datetime DEFAULT NULL,
  `activationKey` varchar(255) DEFAULT NULL,
  `userTheme` varchar(20) DEFAULT NULL,
  `userFont` varchar(20) DEFAULT NULL,
  `totalLeaves` varchar(100) DEFAULT NULL COMMENT 'Total leaves of user',
  `unauthorized` int(11) NOT NULL DEFAULT 0 COMMENT 'if user applies leave within 7 days \r\nunauthorized counts get increase by 1 ',
  `isLeaveManager` tinyint(4) NOT NULL DEFAULT 0,
  `isAccountsPerson` tinyint(1) DEFAULT 0,
  `isHRAdmin` tinyint(1) DEFAULT 0,
  `techIlliterate` tinyint(4) NOT NULL DEFAULT 0 COMMENT 'Non tech person',
  `status` tinyint(1) NOT NULL DEFAULT 1,
  `workStartTime` time DEFAULT NULL COMMENT 'Employee-specific work start time (overrides global)',
  `workEndTime` time DEFAULT NULL COMMENT 'Employee-specific work end time (overrides global)',
  `saturdayStartTime` time DEFAULT NULL COMMENT 'Saturday work start time (if different from regular)',
  `saturdayEndTime` time DEFAULT NULL COMMENT 'Saturday work end time (if different from regular)',
  `isSaturdayOff` tinyint(1) DEFAULT 0,
  `isNonBiometric` tinyint(1) DEFAULT 0,
  `paidLeaveDays` int(11) DEFAULT 12 COMMENT 'Annual paid leave days for this employee',
  `lateGraceMinutes` int(11) DEFAULT NULL COMMENT 'Employee-specific late grace (overrides global)',
  `casualLeaveDays` int(11) DEFAULT 12 COMMENT 'Annual casual leave days',
  `sickLeaveDays` int(11) DEFAULT 12 COMMENT 'Annual sick leave days',
  PRIMARY KEY (`userID`),
  KEY `idx_employee_code` (`employeeCode`),
  KEY `idx_manager` (`managerID`),
  KEY `idx_biometric` (`biometricID`),
  KEY `idx_department` (`department`),
  KEY `idx_whatsapp` (`whatsappNumber`)
) ENGINE=InnoDB AUTO_INCREMENT=24 DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

